shell_commands:
node --input-type=module -e "import {Ajv} from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const validate = ajv.compile({
  type: 'object',
  properties: {
    location: {type: 'string'},
    nested: {type: 'object', properties: {count: {type: 'number'}, mode: {type: 'string', enum: ['a', 'b']}}, required: ['count']}
  },
  required: ['location']
});
validate({nested: {mode: 'c'}});
console.log(JSON.stringify(validate.errors, null, 2));
validate({location: 12345});
console.log(JSON.stringify(validate.errors, null, 2));
"
